package org.humanjourney.core.npc.economy;
import org.humanjourney.core.npc.context.*;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.network.chat.Component;
public final class EconomyDiagnostics {
 public static int role(CommandSourceStack source,String requested){try{var player=source.getPlayerOrException();var resolved=NpcContextRuntime.current(source);if(!resolved.eraProblem().isEmpty())throw new IllegalArgumentException(resolved.eraProblem());var data=NpcContextStore.state().data();String role=requested.startsWith("minecraft:")?"human_journey:"+requested.substring(10):requested;if(!data.archetypes().containsKey(role))throw new IllegalArgumentException("unknown archetype: "+role);if(!data.archetypes().get(role).economy(resolved.context()).enabled())throw new IllegalArgumentException("dynamic economy disabled for "+role);var plan=EconomySpawn.prepare(data,role,resolved.context(),player.registryAccess());String message=resolved.context()+"\nProfile="+plan.profile().values()+"\nmatching sellers="+plan.plan().matchingSellers()+" generated="+plan.plan().offers().size()+"\nskipped="+plan.plan().skipped().entrySet().stream().sorted(java.util.Map.Entry.comparingByKey()).limit(8).toList()+" ("+plan.plan().skipped().size()+" total; economy_match inspects a commodity)";source.sendSuccess(()->Component.literal(message),false);return 1;}catch(Exception e){source.sendFailure(Component.literal("Economy: "+e.getMessage()));return 0;}}
 public static int match(CommandSourceStack source,String requested){try{var context=NpcContextRuntime.current(source).context();var data=NpcContextStore.state().data();String id=requested.startsWith("minecraft:")?"human_journey:"+requested.substring(10):requested;var commodity=data.economy().commodities().get(id);if(commodity==null)throw new IllegalArgumentException("unknown commodity: "+id);var profile=data.geography().profile(context.macroRegion(),context.localArea());String message=id+" era="+commodity.era()+" current="+context.era()+"\nProfile="+profile.values()+"\nSell geography="+commodity.availability().explain(profile)+" overall="+commodity.availability().matches(profile)+" | buy side is never geography-filtered";source.sendSuccess(()->Component.literal(message),false);return 1;}catch(Exception e){source.sendFailure(Component.literal("Economy match: "+e.getMessage()));return 0;}}
 private EconomyDiagnostics(){}
}
